mapper.select:
SELECT id AS id, user_id AS userId, username AS username, role_code AS roleCode, module AS module, operation AS operation, description AS description, request_method AS requestMethod, request_url AS requestUrl, ip_address AS ipAddress, result AS result, DATE_FORMAT(create_time, '%Y-%m-%d %H:%i:%s') AS createTime FROM operation_log WHERE 1 = 1
AND module = #{module}
AND operation = #{operation}
AND result = #{result}
AND user_id = #{userId}
AND (username LIKE CONCAT('%', #{keyword}, '%') OR description LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY id DESC
